# area: paramspec_concatenate
# hypothesis: Concatenate[object, P] keeps its contravariant check when the decorator is a staticmethod on a class, so a callee whose first parameter is str is rejected while an object-typed callee passes.
from collections.abc import Callable
from typing import Concatenate, reveal_type


class Injector:
    @staticmethod
    def inject[**P, R](fn: Callable[Concatenate[object, P], R]) -> Callable[P, R]:
        def inner(*args: P.args, **kwargs: P.kwargs) -> R:
            return fn(Injector(), *args, **kwargs)
        return inner


@Injector.inject
def render(ctx: object, name: str) -> str:
    return f'{type(ctx).__name__}:{name}'


@Injector.inject  # expect-error: callee's first parameter str does not accept object
def narrow(ctx: str, name: str) -> str:
    return ctx + name


reveal_type(render)
reveal_type(narrow)
print(render('ann'))
try:
    print(narrow('x'))
except TypeError as exc:
    print('runtime:', type(exc).__name__)
